// /frontend-react/src/components/MedicalDashboard.js

import React from 'react';

const SubIcon = ({ name, emoji, goToPage, pageTarget, isEasyMode }) => (
    <div 
        onClick={() => goToPage(pageTarget)}
        style={{
            padding: '20px',
            margin: '20px',
            border: '3px solid #007bff',
            borderRadius: '10px',
            width: '80%', // Make icons larger for mobile/easy mode
            textAlign: 'center',
            backgroundColor: 'lightblue',
            cursor: 'pointer',
            fontSize: isEasyMode ? '36px' : '20px',
            boxShadow: '0 4px 8px rgba(0,0,0,0.1)'
        }}
    >
        <span role="img" aria-label={name} style={{fontSize: isEasyMode ? '100px' : '50px'}}>{emoji}</span>
        <p style={{fontWeight: 'bold', margin: '10px 0 0 0'}}>{name}</p>
    </div>
);

function MedicalDashboard({ isEasyMode, goToPage }) {
    return (
        <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', paddingTop: '20px' }}>
            <h2 style={{fontSize: isEasyMode ? '48px' : '30px', margin: '10px'}}>Medical Services</h2>
            
            <SubIcon
                name="Appointment"
                emoji="🧑‍⚕️"
                pageTarget="appointment"
                goToPage={goToPage}
                isEasyMode={isEasyMode}
            />
            
            <SubIcon
                name="Transportation"
                emoji="🚗"
                pageTarget="transport"
                goToPage={goToPage}
                isEasyMode={isEasyMode}
            />
            
            <SubIcon
                name="Medicine"
                emoji="💊"
                pageTarget="medicine" // Need to build this page next
                goToPage={goToPage}
                isEasyMode={isEasyMode}
            />
        </div>
    );
}

export default MedicalDashboard;
